<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\InventoryCountService;
use EventMenu\Services\InventoryService;
use EventMenu\Services\OperatingUnitService;

Auth::requirePermission('inventory.manage');$tenantId=em_require_tenant();$service=new InventoryService();$countService=new InventoryCountService();
try{$unit=(new OperatingUnitService())->requireCurrent();}catch(Throwable$e){em_header('Estoque','inventory');?><div class="alert error"><?= Security::e($e->getMessage()) ?></div><?php em_footer();return;}$unitId=(int)$unit['id'];

if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');
    try{
        if($action==='move'){$productId=(int)($_POST['product_id']??0);$type=(string)($_POST['type']??'');$qty=(float)str_replace(',','.',(string)($_POST['quantity']??'0'));$reason=trim((string)($_POST['reason']??''));$costRaw=trim((string)($_POST['unit_cost']??''));$unitCost=$costRaw===''?null:(int)round((float)str_replace(',','.',$costRaw)*100);$result=$service->move($productId,$type,$qty,$reason,$type==='in'?$unitCost:null);em_flash('ok','Movimentação registrada em '.$unit['name'].'. Custo médio atual: '.em_money((int)($result['average_cost_cents']??0)).'.');em_go('inventory');}
        if($action==='adjust'){$service->setStock((int)($_POST['product_id']??0),(float)str_replace(',','.',(string)($_POST['new_quantity']??'0')),trim((string)($_POST['reason']??'')));em_flash('ok','Saldo disponível ajustado na unidade.');em_go('inventory');}
        if($action==='waste'){$service->waste((int)($_POST['product_id']??0),(float)str_replace(',','.',(string)($_POST['quantity']??'0')),(string)($_POST['reason_type']??'other'),trim((string)($_POST['reason']??'')));em_flash('ok','Perda registrada e baixada do estoque.');em_go('inventory',['tab'=>'waste']);}
        if($action==='count-create'){$id=$countService->create((string)($_POST['notes']??''));em_flash('ok','Contagem física #'.$id.' aberta.');em_go('inventory',['tab'=>'counts','count'=>$id]);}
        if($action==='count-save'){$id=(int)($_POST['count_id']??0);$countService->save($id,(array)($_POST['counts']??[]));em_flash('ok','Contagem salva. Nenhum saldo foi alterado ainda.');em_go('inventory',['tab'=>'counts','count'=>$id]);}
        if($action==='count-approve'){$id=(int)($_POST['count_id']??0);$countService->approve($id);em_flash('ok','Contagem aprovada. Diferenças foram registradas como ajustes auditados.');em_go('inventory',['tab'=>'counts','count'=>$id]);}
        if($action==='count-cancel'){$id=(int)($_POST['count_id']??0);$countService->cancel($id,(string)($_POST['reason']??''));em_flash('ok','Contagem cancelada sem alterar o estoque.');em_go('inventory',['tab'=>'counts']);}
        throw new RuntimeException('Ação inválida.');
    }catch(Throwable$e){em_flash('error',$e->getMessage());$params=[];if(str_starts_with($action,'count-')){$params['tab']='counts';$cid=(int)($_POST['count_id']??0);if($cid)$params['count']=$cid;}em_go('inventory',$params);}
}

$balancesStmt=$pdo->prepare('SELECT p.id,p.name,p.sku,p.stock_unit,p.purchase_unit,p.purchase_factor,p.min_stock_qty,p.active,COALESCE(ui.stock_qty,0) available_qty,COALESCE(ui.average_cost_cents,p.average_cost_cents,0) average_cost_cents,COALESCE(ui.min_stock_qty,p.min_stock_qty,0) unit_min_stock,COALESCE((SELECT SUM(sr.quantity) FROM stock_reservations sr WHERE sr.tenant_id=p.tenant_id AND sr.unit_id=? AND sr.product_id=p.id AND sr.status="reserved"),0) reserved_qty FROM products p LEFT JOIN unit_inventory ui ON ui.tenant_id=p.tenant_id AND ui.unit_id=? AND ui.product_id=p.id WHERE p.tenant_id=? AND p.track_stock=1 ORDER BY p.active DESC,p.name');$balancesStmt->execute([$unitId,$unitId,$tenantId]);$products=$balancesStmt->fetchAll();
$low=[];$reservedTotal=0.0;$inventoryValue=0;foreach($products as&$row){$row['physical_qty']=(float)$row['available_qty']+(float)$row['reserved_qty'];$row['value_cents']=(int)round($row['physical_qty']*(int)$row['average_cost_cents']);if((float)$row['available_qty']<=(float)$row['unit_min_stock'])$low[]=$row;$reservedTotal+=(float)$row['reserved_qty'];$inventoryValue+=$row['value_cents'];}unset($row);
$movementStmt=$pdo->prepare('SELECT sm.*,p.name product_name,p.sku,u.name performed_by_name,o.id linked_order FROM stock_movements sm JOIN products p ON p.id=sm.product_id LEFT JOIN users u ON u.id=sm.performed_by LEFT JOIN orders o ON o.id=sm.order_id WHERE sm.tenant_id=? AND sm.unit_id=? ORDER BY sm.id DESC LIMIT 250');$movementStmt->execute([$tenantId,$unitId]);$movements=$movementStmt->fetchAll();
$reservationStmt=$pdo->prepare('SELECT sr.*,p.name product_name,p.stock_unit,o.status order_status,o.payment_status FROM stock_reservations sr JOIN products p ON p.id=sr.product_id JOIN orders o ON o.id=sr.order_id WHERE sr.tenant_id=? AND sr.unit_id=? AND sr.status="reserved" ORDER BY sr.id DESC LIMIT 150');$reservationStmt->execute([$tenantId,$unitId]);$reservations=$reservationStmt->fetchAll();
$wasteStmt=$pdo->prepare('SELECT iw.*,p.name product_name,p.stock_unit,u.name user_name FROM inventory_waste iw JOIN products p ON p.id=iw.product_id LEFT JOIN users u ON u.id=iw.user_id WHERE iw.tenant_id=? AND iw.unit_id=? ORDER BY iw.id DESC LIMIT 150');$wasteStmt->execute([$tenantId,$unitId]);$wastes=$wasteStmt->fetchAll();$wasteCost=array_sum(array_map(static fn(array$w):int=>(int)$w['cost_cents'],$wastes));
$counts=$countService->list(80);$countId=(int)($_GET['count']??0);$countDetail=null;if($countId){try{$countDetail=$countService->details($countId);}catch(Throwable$e){em_flash('error',$e->getMessage());}}
$selected=(int)($_GET['product_id']??0);$tab=(string)($_GET['tab']??'stock');if(!in_array($tab,['stock','counts','waste','history'],true))$tab='stock';$reasonLabels=['expired'=>'Vencimento','breakage'=>'Quebra / avaria','production_error'=>'Erro de produção','internal_use'=>'Consumo interno','courtesy'=>'Cortesia','waste'=>'Desperdício','other'=>'Outro'];
em_header('Estoque','inventory');
?>
<section class="page-hero"><div><span class="eyebrow">ESTOQUE · <?= Security::e($unit['name']) ?></span><h2>Controle de estoque</h2><p>Saldo, reservas, custo médio, compras, perdas e contagem física são isolados por unidade. O saldo disponível já desconta reservas feitas para pedidos.</p></div><div class="hero-actions"><a class="button primary" href="<?= Security::e(app_url('?route=purchases')) ?>">Compras / Fornecedores</a><a class="button secondary" href="<?= Security::e(app_url('?route=products')) ?>">Produtos</a></div></section>
<section class="grid dashboard-metrics"><div class="card metric"><span class="muted">Produtos controlados</span><strong><?= count($products) ?></strong></div><div class="card metric"><span class="muted">Abaixo do mínimo</span><strong><?= count($low) ?></strong></div><div class="card metric"><span class="muted">Reservado em pedidos</span><strong><?= Security::e((string)$reservedTotal) ?></strong></div><div class="card metric"><span class="muted">Valor físico estimado</span><strong><?= em_money($inventoryValue) ?></strong></div></section>
<nav class="actions" style="margin:18px 0"><a class="button <?= $tab==='stock'?'primary':'secondary' ?>" href="<?= Security::e(app_url('?route=inventory&tab=stock')) ?>">Saldos</a><a class="button <?= $tab==='counts'?'primary':'secondary' ?>" href="<?= Security::e(app_url('?route=inventory&tab=counts')) ?>">Contagem física</a><a class="button <?= $tab==='waste'?'primary':'secondary' ?>" href="<?= Security::e(app_url('?route=inventory&tab=waste')) ?>">Perdas</a><a class="button <?= $tab==='history'?'primary':'secondary' ?>" href="<?= Security::e(app_url('?route=inventory&tab=history')) ?>">Movimentações</a></nav>
<?php if($tab==='stock'):?>
<div class="grid" style="grid-template-columns:minmax(310px,.9fr) minmax(0,1.8fr)"><section class="card"><span class="eyebrow">MOVIMENTAÇÃO MANUAL</span><h2>Entrada ou saída</h2><?php if(!$products):?><p class="muted">Nenhum produto com controle de estoque ativo.</p><?php else:?><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="move"><label class="span-2">Produto<select name="product_id" required><?php foreach($products as$p):?><option value="<?= (int)$p['id'] ?>"<?= em_selected($selected,$p['id']) ?>><?= Security::e($p['name'].' · '.(string)$p['available_qty'].' '.$p['stock_unit']) ?></option><?php endforeach;?></select></label><label>Tipo<select name="type"><option value="in">Entrada manual</option><option value="out">Saída manual</option></select></label><label>Quantidade<input name="quantity" inputmode="decimal" required></label><label class="span-2">Custo unitário da entrada (R$)<input name="unit_cost" inputmode="decimal" placeholder="Opcional"><small>Para compras regulares, prefira o módulo Compras / Fornecedores.</small></label><label class="span-2">Motivo<textarea name="reason" required maxlength="500" placeholder="Transferência, acerto operacional, entrada inicial..."></textarea></label><button class="primary span-2">Registrar movimento</button></form><hr style="border-color:var(--line);margin:24px 0"><h3>Ajuste direto do disponível</h3><p class="muted">Use para correção pontual. Para inventário completo, use Contagem física.</p><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="adjust"><label class="span-2">Produto<select name="product_id" required><?php foreach($products as$p):?><option value="<?= (int)$p['id'] ?>"<?= em_selected($selected,$p['id']) ?>><?= Security::e($p['name'].' · disponível '.$p['available_qty'].' · reservado '.$p['reserved_qty']) ?></option><?php endforeach;?></select></label><label class="span-2">Novo saldo disponível<input name="new_quantity" inputmode="decimal" required></label><label class="span-2">Motivo<textarea name="reason" required maxlength="500"></textarea></label><button class="secondary span-2">Ajustar saldo</button></form><?php endif;?></section><section class="card"><div class="section-head"><div><span class="eyebrow">SALDO DA UNIDADE</span><h2><?= Security::e($unit['name']) ?></h2></div><span class="muted">disponível + reservado = físico</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Produto</th><th>Disponível</th><th>Reservado</th><th>Físico</th><th>Mínimo</th><th>Custo médio</th><th>Valor</th><th>Status</th></tr></thead><tbody><?php foreach($products as$p):$available=(float)$p['available_qty'];$minimum=(float)$p['unit_min_stock'];?><tr><td><strong><?= Security::e($p['name']) ?></strong><br><span class="muted"><?= Security::e($p['sku']??'Sem SKU') ?> · <?= Security::e($p['stock_unit']) ?></span></td><td><strong><?= Security::e((string)$p['available_qty']) ?></strong></td><td><?= Security::e((string)$p['reserved_qty']) ?></td><td><?= Security::e((string)$p['physical_qty']) ?></td><td><?= Security::e((string)$minimum) ?></td><td><?= em_money($p['average_cost_cents']) ?></td><td><?= em_money($p['value_cents']) ?></td><td><span class="status-pill <?= $available<=$minimum?'cancelled':'active' ?>"><?= $available<=0?'ZERADO':($available<=$minimum?'BAIXO':'OK') ?></span></td></tr><?php endforeach;?><?php if(!$products):?><tr><td colspan="8">Nenhum produto controlado.</td></tr><?php endif;?></tbody></table></div></section></div>
<section class="card" style="margin-top:18px"><div class="section-head"><h2>Reservas ativas</h2><span class="muted">estoque separado para pedidos ainda não consumidos</span></div><?php if(!$reservations):?><p class="muted">Nenhuma reserva ativa nesta unidade.</p><?php else:?><div class="table-wrap"><table class="table"><thead><tr><th>Pedido</th><th>Produto</th><th>Quantidade</th><th>Pedido</th><th>Pagamento</th><th>Expiração</th></tr></thead><tbody><?php foreach($reservations as$r):?><tr><td><a href="<?= Security::e(app_url('?route=orders&view='.(int)$r['order_id'])) ?>">#<?= (int)$r['order_id'] ?></a></td><td><?= Security::e($r['product_name']) ?></td><td><?= Security::e((string)$r['quantity'].' '.$r['stock_unit']) ?></td><td><?= Security::e($r['order_status']) ?></td><td><?= Security::e($r['payment_status']) ?></td><td><?= Security::e($r['expires_at']??'Sem expiração') ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php elseif($tab==='counts'):?>
<div class="grid" style="grid-template-columns:minmax(280px,.7fr) minmax(0,1.8fr)"><section class="card"><span class="eyebrow">NOVO INVENTÁRIO</span><h2>Abrir contagem</h2><p>O EventMenu salva uma fotografia do estoque físico esperado. Enquanto você conta, nenhum saldo é alterado.</p><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="count-create"><label class="span-2">Observação<textarea name="notes" placeholder="Ex.: Fechamento semanal"></textarea></label><button class="primary span-2">Abrir contagem física</button></form><hr style="border-color:var(--line);margin:24px 0"><h3>Contagens da unidade</h3><?php foreach($counts as$c):?><a class="card" style="display:block;margin:8px 0;padding:12px;text-decoration:none" href="<?= Security::e(app_url('?route=inventory&tab=counts&count='.(int)$c['id'])) ?>"><div class="section-head"><strong>#<?= (int)$c['id'] ?></strong><span class="status-pill <?= $c['status']==='approved'?'active':($c['status']==='cancelled'?'cancelled':'') ?>"><?= Security::e($c['status']) ?></span></div><small class="muted"><?= (int)$c['items_counted'] ?>/<?= (int)$c['items_total'] ?> contados · <?= (int)$c['differences'] ?> diferenças</small></a><?php endforeach;?><?php if(!$counts):?><p class="muted">Nenhuma contagem registrada.</p><?php endif;?></section><section class="card"><?php if(!$countDetail):?><div class="alert">Abra ou selecione uma contagem para começar.</div><?php else:$ic=$countDetail['count'];$open=$ic['status']==='open';?><div class="section-head"><div><span class="eyebrow">CONTAGEM #<?= (int)$ic['id'] ?></span><h2><?= Security::e($ic['unit_name']) ?></h2><p class="muted">Criada por <?= Security::e($ic['created_by_name']??'Sistema') ?> em <?= Security::e($ic['created_at']) ?></p></div><span class="status-pill <?= $ic['status']==='approved'?'active':($ic['status']==='cancelled'?'cancelled':'') ?>"><?= Security::e(strtoupper($ic['status'])) ?></span></div><?php if($open):?><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="count-save"><input type="hidden" name="count_id" value="<?= (int)$ic['id'] ?>"><?php endif;?><div class="table-wrap"><table class="table"><thead><tr><th>Produto</th><th>Esperado físico</th><th>Reservado agora</th><th>Contado físico</th><th>Diferença</th></tr></thead><tbody><?php foreach($countDetail['items'] as$i):$diff=$i['difference_qty'];?><tr><td><strong><?= Security::e($i['product_name']) ?></strong><br><span class="muted"><?= Security::e($i['sku']??'') ?> · <?= Security::e($i['stock_unit']) ?></span></td><td><?= Security::e((string)$i['expected_qty']) ?></td><td><?= Security::e((string)$i['reserved_now']) ?></td><td><?php if($open):?><input name="counts[<?= (int)$i['id'] ?>]" inputmode="decimal" value="<?= $i['counted_qty']!==null?Security::e((string)$i['counted_qty']):'' ?>" style="min-width:90px"><?php else:?><strong><?= $i['counted_qty']!==null?Security::e((string)$i['counted_qty']):'—' ?></strong><?php endif;?></td><td><?= $diff===null?'—':Security::e(((float)$diff>0?'+':'').(string)$diff) ?></td></tr><?php endforeach;?></tbody></table></div><?php if($open):?><div class="actions" style="margin-top:18px"><button class="secondary">Salvar contagem</button></div></form><div class="actions" style="margin-top:10px"><?php if(Auth::can('inventory.approve')):?><form method="post" onsubmit="return confirm('Aprovar a contagem e aplicar as diferenças ao estoque?')"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="count-approve"><input type="hidden" name="count_id" value="<?= (int)$ic['id'] ?>"><button class="primary">Aprovar e ajustar estoque</button></form><?php endif;?><form method="post" onsubmit="return confirm('Cancelar esta contagem sem alterar estoque?')"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="count-cancel"><input type="hidden" name="count_id" value="<?= (int)$ic['id'] ?>"><input type="hidden" name="reason" value="Cancelada pelo operador"><button class="secondary">Cancelar contagem</button></form></div><?php else:?><div class="alert">Esta contagem está encerrada. <?php if($ic['approved_by_name']):?>Aprovada por <strong><?= Security::e($ic['approved_by_name']) ?></strong>.<?php endif;?></div><?php endif;?><?php endif;?></section></div>
<?php elseif($tab==='waste'):?>
<div class="grid" style="grid-template-columns:minmax(300px,.8fr) minmax(0,1.8fr)"><section class="card"><span class="eyebrow">BAIXA CONTROLADA</span><h2>Registrar perda</h2><p class="muted">Quebra, vencimento, erro de produção, consumo interno e outras perdas reduzem o saldo e preservam o custo para análise.</p><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="waste"><label class="span-2">Produto<select name="product_id" required><?php foreach($products as$p):?><option value="<?= (int)$p['id'] ?>"><?= Security::e($p['name'].' · disponível '.$p['available_qty'].' '.$p['stock_unit']) ?></option><?php endforeach;?></select></label><label>Quantidade<input name="quantity" inputmode="decimal" required></label><label>Tipo<select name="reason_type"><?php foreach($reasonLabels as$value=>$label):?><option value="<?= $value ?>"><?= Security::e($label) ?></option><?php endforeach;?></select></label><label class="span-2">Detalhes<textarea name="reason" maxlength="500"></textarea></label><button class="primary span-2">Registrar perda</button></form></section><section class="card"><div class="section-head"><div><h2>Perdas recentes</h2><span class="muted">Custo acumulado mostrado: <?= em_money($wasteCost) ?></span></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Produto</th><th>Quantidade</th><th>Tipo</th><th>Custo</th><th>Responsável</th><th>Detalhes</th></tr></thead><tbody><?php foreach($wastes as$w):?><tr><td><?= Security::e($w['created_at']) ?></td><td><strong><?= Security::e($w['product_name']) ?></strong></td><td><?= Security::e((string)$w['quantity'].' '.$w['stock_unit']) ?></td><td><?= Security::e($reasonLabels[$w['reason_type']]??$w['reason_type']) ?></td><td><?= em_money($w['cost_cents']) ?></td><td><?= Security::e($w['user_name']??'Sistema') ?></td><td><?= Security::e($w['reason']??'—') ?></td></tr><?php endforeach;?><?php if(!$wastes):?><tr><td colspan="7">Nenhuma perda registrada nesta unidade.</td></tr><?php endif;?></tbody></table></div></section></div>
<?php else:?>
<section class="card"><div class="section-head"><div><span class="eyebrow">AUDITORIA OPERACIONAL</span><h2>Movimentações da unidade</h2></div><span class="muted"><?= count($movements) ?> registros exibidos</span></div><div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>Data</th><th>Produto</th><th>Tipo</th><th>Qtd.</th><th>Custo un.</th><th>Custo total</th><th>Pedido</th><th>Responsável</th><th>Motivo</th></tr></thead><tbody><?php foreach($movements as$m):?><tr><td>#<?= (int)$m['id'] ?></td><td><?= Security::e($m['created_at']??'') ?></td><td><strong><?= Security::e($m['product_name']) ?></strong></td><td><span class="badge"><?= Security::e($m['type']) ?></span></td><td><?= Security::e((string)$m['quantity']) ?></td><td><?= $m['unit_cost_cents']!==null?em_money($m['unit_cost_cents']):'—' ?></td><td><?= $m['total_cost_cents']!==null?em_money(abs((int)$m['total_cost_cents'])):'—' ?></td><td><?= $m['linked_order']?'#'.(int)$m['linked_order']:'—' ?></td><td><?= Security::e($m['performed_by_name']??'Sistema') ?></td><td><?= Security::e($m['reason']??'—') ?></td></tr><?php endforeach;?><?php if(!$movements):?><tr><td colspan="10">Nenhuma movimentação nesta unidade.</td></tr><?php endif;?></tbody></table></div></section>
<?php endif;em_footer();
